// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./VaultToken.sol";

contract VaultFactory is Ownable {
    mapping(bytes32 => address) public vaultTokens;
    mapping(address => bool) public isVaultToken;

    event VaultTokenCreated(
        uint256 indexed nftId,
        address indexed nftContract,
        address vaultToken,
        uint256 totalSupply
    );

    constructor() {
        _transferOwnership(msg.sender);
    }

    function createVaultToken(
        uint256 nftId,
        address nftContract,
        uint256 totalSupply,
        string memory name,
        string memory symbol
    ) external returns (address) {
        bytes32 key = keccak256(abi.encodePacked(nftId, nftContract));
        require(vaultTokens[key] == address(0), "Vault token already exists");

        VaultToken vaultToken = new VaultToken(
            nftId,
            nftContract,
            totalSupply,
            name,
            symbol,
            tx.origin // The original caller (NFT creator)
        );

        address vaultAddress = address(vaultToken);
        vaultTokens[key] = vaultAddress;
        isVaultToken[vaultAddress] = true;

        emit VaultTokenCreated(nftId, nftContract, vaultAddress, totalSupply);

        return vaultAddress;
    }

    function getVaultToken(uint256 nftId, address nftContract) external view returns (address) {
        bytes32 key = keccak256(abi.encodePacked(nftId, nftContract));
        return vaultTokens[key];
    }
}

contracts/VaultToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract VaultToken is ERC20, Ownable {
    uint256 public immutable nftId;
    address public immutable nftContract;

    constructor(
        uint256 _nftId,
        address _nftContract,
        uint256 _totalSupply,
        string memory _name,
        string memory _symbol,
        address _creator
    ) ERC20(_name, _symbol) {
        nftId = _nftId;
        nftContract = _nftContract;
        _mint(_creator, _totalSupply);
        _transferOwnership(_creator);
    }

    function decimals() public pure override returns (uint8) {
        return 0; // No decimal places for share tokens
    }

    // Only allow the NFT contract to mint additional tokens if needed
    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    // Allow burning tokens to potentially reclaim full NFT ownership
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }

    // Get the percentage ownership of an address
    function getOwnershipPercentage(address account) external view returns (uint256) {
        if (totalSupply() == 0) return 0;
        return (balanceOf(account) * 100) / totalSupply();
    }
}

